import{_ as e,C as t,c as r,o as i,j as a,b as o,a0 as s,a as l,w as n,G as u,a1 as h}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Handling Pressure","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/mental-strength/handling-pressure.md","filePath":"en/education/mental-strength/handling-pressure.md"}');const d=e({name:"en/education/mental-strength/handling-pressure.md"},[["render",function(e,c,d,p,m,g){const f=t("Mermaid");return i(),r("div",null,[c[1]||(c[1]=a("h1",{id:"handling-pressure",tabindex:"-1"},[l("Handling Pressure "),a("a",{class:"header-anchor",href:"#handling-pressure","aria-label":'Permalink to "Handling Pressure"'},"​")],-1)),c[2]||(c[2]=a("p",null,"Pressure is part of competition. The goal isn't to eliminate it - that's impossible. The goal is to perform well despite it, and even use it to your advantage.",-1)),c[3]||(c[3]=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"The Big Idea"),a("p",null,[a("strong",null,"Pressure doesn't go away with experience - you just get better at performing with it."),l(" The best players aren't calm; they're skilled at using their arousal productively.")])],-1)),(i(),o(h,null,{default:n(()=>[u(f,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPressure%20Situation%5D%20--%3E%20B%7BYour%20Response%7D%0A%20%20%20%20B%20--%3E%7CAnxiety%7C%20C%5BPerformance%20Drops%5D%0A%20%20%20%20B%20--%3E%7CExcitement%7C%20D%5BPerformance%20Rises%5D%0A%0A%20%20%20%20C%20--%3E%20E%5BNegative%20Thoughts%5D%0A%20%20%20%20C%20--%3E%20F%5BTension%5D%0A%20%20%20%20C%20--%3E%20G%5BPoor%20Focus%5D%0A%0A%20%20%20%20D%20--%3E%20H%5BEnergized%5D%0A%20%20%20%20D%20--%3E%20I%5BFocused%5D%0A%20%20%20%20D%20--%3E%20J%5BConfident%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A"})]),fallback:n(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=s('<h2 id="understanding-pressure" tabindex="-1">Understanding Pressure <a class="header-anchor" href="#understanding-pressure" aria-label="Permalink to &quot;Understanding Pressure&quot;">​</a></h2><h3 id="what-creates-pressure" tabindex="-1">What Creates Pressure? <a class="header-anchor" href="#what-creates-pressure" aria-label="Permalink to &quot;What Creates Pressure?&quot;">​</a></h3><ul><li>High stakes (important game, decisive throw)</li><li>Being watched (audience, teammates)</li><li>Expectations (yours and others&#39;)</li><li>Uncertainty (close score, unfamiliar opponents)</li><li>Time (running out, waiting too long)</li></ul><h3 id="what-pressure-does-to-your-body" tabindex="-1">What Pressure Does to Your Body <a class="header-anchor" href="#what-pressure-does-to-your-body" aria-label="Permalink to &quot;What Pressure Does to Your Body&quot;">​</a></h3><p>When you feel pressure, your body responds:</p><ul><li>Heart rate increases</li><li>Breathing becomes shallow</li><li>Muscles tense</li><li>Hands may shake</li><li>Focus narrows (sometimes too much)</li></ul><p>This is your body preparing for action. It&#39;s not bad - it&#39;s energy you can use.</p><h2 id="reframing-pressure" tabindex="-1">Reframing Pressure <a class="header-anchor" href="#reframing-pressure" aria-label="Permalink to &quot;Reframing Pressure&quot;">​</a></h2><h3 id="pressure-as-excitement" tabindex="-1">Pressure as Excitement <a class="header-anchor" href="#pressure-as-excitement" aria-label="Permalink to &quot;Pressure as Excitement&quot;">​</a></h3><p>The physical sensations of anxiety and excitement are almost identical. The difference is how you interpret them.</p><p><strong>Anxiety interpretation:</strong> &quot;I&#39;m nervous, something bad might happen&quot; <strong>Excitement interpretation:</strong> &quot;I&#39;m energized, this is important to me&quot;</p><p><strong>Try this:</strong> When you feel pressure, say to yourself: &quot;I&#39;m excited&quot; instead of &quot;I&#39;m nervous.&quot;</p><h3 id="pressure-as-privilege" tabindex="-1">Pressure as Privilege <a class="header-anchor" href="#pressure-as-privilege" aria-label="Permalink to &quot;Pressure as Privilege&quot;">​</a></h3><p>Only important moments create pressure. If you&#39;re feeling it, you&#39;re in a situation that matters.</p><blockquote><p>&quot;Pressure is a privilege - it only comes to those who earn it.&quot; - Billie Jean King</p></blockquote><h2 id="techniques-for-high-pressure-moments" tabindex="-1">Techniques for High-Pressure Moments <a class="header-anchor" href="#techniques-for-high-pressure-moments" aria-label="Permalink to &quot;Techniques for High-Pressure Moments&quot;">​</a></h2><h3 id="_1-breath-control" tabindex="-1">1. Breath Control <a class="header-anchor" href="#_1-breath-control" aria-label="Permalink to &quot;1. Breath Control&quot;">​</a></h3><p>Your breath is the fastest way to change your state.</p><p><strong>The 4-7-8 Technique:</strong></p><ol><li>Inhale for 4 counts</li><li>Hold for 7 counts</li><li>Exhale for 8 counts</li><li>Repeat 2-3 times</li></ol><p><strong>Quick reset (in the circle):</strong></p><ul><li>One slow, deep breath</li><li>Feel your feet on the ground</li><li>Drop your shoulders on the exhale</li></ul><h3 id="_2-physical-grounding" tabindex="-1">2. Physical Grounding <a class="header-anchor" href="#_2-physical-grounding" aria-label="Permalink to &quot;2. Physical Grounding&quot;">​</a></h3><p>Connect with physical sensations to get out of your head:</p><ul><li>Feel the weight of the boule</li><li>Notice your feet on the ground</li><li>Squeeze and release your non-throwing hand</li><li>Roll your shoulders back</li></ul><h3 id="_3-focus-narrowing" tabindex="-1">3. Focus Narrowing <a class="header-anchor" href="#_3-focus-narrowing" aria-label="Permalink to &quot;3. Focus Narrowing&quot;">​</a></h3><p>In pressure moments, focus only on what matters:</p><ul><li>Not the score</li><li>Not the audience</li><li>Not what might happen</li><li>Just this throw, this target, this moment</li></ul><p><strong>Cue words:</strong> &quot;Here. Now. This.&quot;</p><h3 id="_4-process-focus" tabindex="-1">4. Process Focus <a class="header-anchor" href="#_4-process-focus" aria-label="Permalink to &quot;4. Process Focus&quot;">​</a></h3><p>Shift from outcome to process:</p><p><strong>Outcome focus (creates pressure):</strong></p><ul><li>&quot;I need to make this&quot;</li><li>&quot;If I miss, we lose&quot;</li><li>&quot;Everyone is watching&quot;</li></ul><p><strong>Process focus (reduces pressure):</strong></p><ul><li>&quot;Follow my routine&quot;</li><li>&quot;See the target&quot;</li><li>&quot;Trust my training&quot;</li></ul><h3 id="_5-the-left-hand-squeeze" tabindex="-1">5. The Left-Hand Squeeze <a class="header-anchor" href="#_5-the-left-hand-squeeze" aria-label="Permalink to &quot;5. The Left-Hand Squeeze&quot;">​</a></h3><p>For right-handed players, squeezing your left hand for 10-15 seconds:</p><ul><li>Activates the right brain hemisphere</li><li>Quiets analytical overthinking</li><li>Helps access automatic execution</li></ul><p>Use this when you notice yourself overthinking.</p><h2 id="preparing-for-pressure" tabindex="-1">Preparing for Pressure <a class="header-anchor" href="#preparing-for-pressure" aria-label="Permalink to &quot;Preparing for Pressure&quot;">​</a></h2><h3 id="simulate-pressure-in-practice" tabindex="-1">Simulate Pressure in Practice <a class="header-anchor" href="#simulate-pressure-in-practice" aria-label="Permalink to &quot;Simulate Pressure in Practice&quot;">​</a></h3><p>You can&#39;t handle competition pressure if you never experience it in training.</p><p><strong>Ways to create practice pressure:</strong></p><ul><li>Set consequences (push-ups for misses, buy coffee for partner)</li><li>Create &quot;must-make&quot; scenarios</li><li>Practice with an audience</li><li>Time pressure (shot clock)</li><li>Fatigue (practice when tired)</li></ul><h3 id="visualization" tabindex="-1">Visualization <a class="header-anchor" href="#visualization" aria-label="Permalink to &quot;Visualization&quot;">​</a></h3><p>Mentally rehearse high-pressure situations:</p><ol><li>Close your eyes</li><li>Imagine a pressure scenario in detail</li><li>Feel the pressure sensations</li><li>See yourself handling it well</li><li>Execute successfully in your mind</li></ol><p>Do this regularly, not just before competitions.</p><h3 id="build-a-pressure-history" tabindex="-1">Build a Pressure History <a class="header-anchor" href="#build-a-pressure-history" aria-label="Permalink to &quot;Build a Pressure History&quot;">​</a></h3><p>Keep track of times you&#39;ve handled pressure well:</p><ul><li>What was the situation?</li><li>How did you feel?</li><li>What did you do?</li><li>What was the result?</li></ul><p>Review this before competitions to remind yourself: &quot;I&#39;ve done this before.&quot;</p><h2 id="during-competition" tabindex="-1">During Competition <a class="header-anchor" href="#during-competition" aria-label="Permalink to &quot;During Competition&quot;">​</a></h2><h3 id="before-the-pressure-throw" tabindex="-1">Before the Pressure Throw <a class="header-anchor" href="#before-the-pressure-throw" aria-label="Permalink to &quot;Before the Pressure Throw&quot;">​</a></h3><ol><li>Step back, take a breath</li><li>Remind yourself of your routine</li><li>Focus on process, not outcome</li><li>Use your trigger word or cue</li></ol><h3 id="in-the-circle" tabindex="-1">In the Circle <a class="header-anchor" href="#in-the-circle" aria-label="Permalink to &quot;In the Circle&quot;">​</a></h3><ol><li>Complete your routine exactly as practiced</li><li>Focus externally (target, not body)</li><li>Trust your training</li><li>Release without hesitation</li></ol><h3 id="after-the-throw" tabindex="-1">After the Throw <a class="header-anchor" href="#after-the-throw" aria-label="Permalink to &quot;After the Throw&quot;">​</a></h3><ul><li>Accept the result without judgment</li><li>If good: brief acknowledgment, move on</li><li>If bad: SOAS method, reset for next throw</li></ul><h2 id="common-pressure-mistakes" tabindex="-1">Common Pressure Mistakes <a class="header-anchor" href="#common-pressure-mistakes" aria-label="Permalink to &quot;Common Pressure Mistakes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mistake</th><th>Better Approach</th></tr></thead><tbody><tr><td>Rushing</td><td>Slow down, use full routine</td></tr><tr><td>Overthinking</td><td>External focus, trust training</td></tr><tr><td>Changing technique</td><td>Stick with what you know</td></tr><tr><td>Focusing on outcome</td><td>Focus on process</td></tr><tr><td>Fighting nerves</td><td>Accept and use the energy</td></tr></tbody></table><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>Pressure doesn&#39;t go away with experience. You just get better at performing with it.</p></blockquote><p>The best players aren&#39;t calm - they&#39;re skilled at using their arousal productively.</p>',64))])}]]);export{c as __pageData,d as default};
